    public record SplitChild(
            String batchKey,
            String batchNo,
            String productCode,
            Instant producedAt,
            BatchStatus status,
            List<String> requiredTests,
            Instant createdAt,
            BigDecimal quantity,
            BigDecimal initialPotency,
            BigDecimal minReleasePotency,
            BigDecimal decayRatePerDay,
            Instant potencyEpochAt
    ) {
    }
}

