    @Test
    void modelRevision_doesNotRewriteHistory_andReleaseReadsConsistentModel() throws Exception {
        // 版本 1（scale 4）下放行批次 A：97.65 原样保留
        String batchA = "BK-PM-A-" + unique();
        createPotent(batchA, "97.65", "90", "0", "10");
